{
  "tasks": [
    {
      "task_id": "T1",
      "title": "统计非丙项目已完成任务的工时总和",
      "business_question": "按项目统计已完成任务的工时总和，不包含丙项目。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“按项目统计已完成任务的工时总和，不包含丙项目”，删除后无法支持该决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0002",
                "operator": "ne",
                "value": "丙项目"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
